document.addEventListener("DOMContentLoaded",function(){const t=document.getElementById("stair-stringer-form"),n=document.getElementById("stair-stringer-result");t&&t.addEventListener("submit",function(t){t.preventDefault();const e=parseFloat(document.getElementById("stringer-total-rise").value),r=parseFloat(document.getElementById("stringer-total-run").value),i=parseFloat(document.getElementById("stringer-width").value),[s,o]=document.getElementById("stringer-lumber").value.split(","),a=parseFloat(o);if(e<=0||r<=0||i<=0)return n.textContent="Please enter valid measurements.",void 0;const p=Math.round(e/7.5),l=e/p,d=p-1,u=r/d,c=l>=4&&l<=7.75,g=u>=10,m=Math.floor(i/16)+1,h=i/(m-1),$=Math.sqrt(Math.pow(e,2)+Math.pow(r,2))/12,f=a-l,v=f>=5,F=25*m,x=d*(i/12)*4,b=p*(i/12)*3,C=F+x+b+50,M=Math.atan(e/r)*(180/Math.PI),w=90-M,y=M;n.innerHTML=`\n        <div class="result-section">\n          <h4>Stair Calculations:</h4>\n          <p><strong>${p} risers</strong> @ ${l.toFixed(3)}" each</p>\n          <p><strong>${d} treads</strong> @ ${u.toFixed(2)}" each</p>\n          <p>Total rise: ${e}"</p>\n          <p>Total run: ${r}"</p>\n          <p>Stair angle: ${M.toFixed(1)}°</p>\n        </div>\n        \n        <div class="result-stringers">\n          <h4>Stringer Requirements:</h4>\n          <p><strong>${m} stringers needed</strong></p>\n          <p>Stringer spacing: ${h.toFixed(1)}" on center</p>\n          <p>Lumber: ${m} pieces of ${s}×16'</p>\n          <p>Stringer length: ${$.toFixed(1)} feet</p>\n          <p>Material depth: ${a}" (${s})</p>\n        </div>\n        \n        <div class="result-compliance">\n          <h4>Code Compliance:</h4>\n          <p>Riser height: ${c?"✅ Compliant":"❌ Non-compliant"} (${l.toFixed(2)}")</p>\n          <p>Tread depth: ${g?"✅ Compliant":"❌ Non-compliant"} (${u.toFixed(2)}")</p>\n          <p>Remaining lumber: ${v?"✅ Adequate":"❌ Insufficient"} (${f.toFixed(1)}")</p>\n          <p>Uniformity: ✅ All steps identical</p>\n        </div>\n        \n        <div class="result-cutting">\n          <h4>Cutting Information:</h4>\n          <p><strong>Plumb cut angle: ${w.toFixed(1)}°</strong></p>\n          <p><strong>Level cut angle: ${y.toFixed(1)}°</strong></p>\n          <p>Tread cut depth: ${u.toFixed(2)}"</p>\n          <p>Riser cut depth: ${l.toFixed(2)}"</p>\n          <p>Bottom cut: Level cut for landing</p>\n          <p>Top cut: Plumb cut for attachment</p>\n        </div>\n        \n        <div class="result-layout">\n          <h4>Layout Instructions:</h4>\n          <p>1. Mark first riser at top of board</p>\n          <p>2. Use framing square with ${u.toFixed(1)}" and ${l.toFixed(1)}" settings</p>\n          <p>3. Mark all treads and risers consistently</p>\n          <p>4. Mark plumb and level cuts at ends</p>\n          <p>5. Cut first stringer and test fit</p>\n          <p>6. Use as template for remaining stringers</p>\n        </div>\n        \n        <div class="result-materials">\n          <h4>Material Costs:</h4>\n          <p>Stringers: $${F} (${m} @ $25 each)</p>\n          <p>Treads: $${x.toFixed(0)} (${d} @ ${(i/12).toFixed(1)} bd ft each)</p>\n          <p>Risers: $${b.toFixed(0)} (${p} @ ${(i/12).toFixed(1)} bd ft each)</p>\n          <p>Hardware: $50</p>\n          <p><strong>Total: $${C.toFixed(0)}</strong></p>\n        </div>\n        \n        <div class="result-tools">\n          <h4>Tools Required:</h4>\n          <p>📐 Framing square (for layout)</p>\n          <p>🪚 Circular saw (main cuts)</p>\n          <p>🔧 Jigsaw (plunge cuts)</p>\n          <p>📏 Measuring tape</p>\n          <p>✏️ Pencil for marking</p>\n          <p>📊 Level (checking fit)</p>\n        </div>\n        \n        <div class="result-installation">\n          <h4>Installation Tips:</h4>\n          <p>🔗 Attach top with joist hangers or ledger</p>\n          <p>⚓ Secure bottom to concrete pad or footing</p>\n          <p>📏 Check for level and plumb</p>\n          <p>🔧 Install treads with 2.5" deck screws</p>\n          <p>🛡️ Apply weather protection for outdoor stairs</p>\n        </div>\n        \n        ${c&&g&&v?"":`\n        <div class="result-warnings">\n          <h4>⚠️ Issues Detected:</h4>\n          ${c?"":`<p>Riser height ${l.toFixed(2)}" outside 4"-7.75" code range</p>`}\n          ${g?"":`<p>Tread depth ${u.toFixed(2)}" below 10" minimum</p>`}\n          ${v?"":`<p>Only ${f.toFixed(1)}" lumber remaining (need 5" minimum)</p>`}\n          <p>Consider adjusting total rise/run or using larger lumber</p>\n        </div>\n        `}\n        \n        <div class="result-tips">\n          <h4>Professional Tips:</h4>\n          <p>🎯 Cut one stringer first and test-fit before cutting others</p>\n          <p>📝 Always round measurements to nearest 1/16"</p>\n          <p>🔍 Double-check calculations before cutting expensive lumber</p>\n          <p>🏗️ Consider hiring professionals for complex or structural stairs</p>\n        </div>\n      `})});